import math
from collections import deque


def best_average(a: list[int], k: int) -> list[int]:
    n = len(a)
    prefix = [0] * (n + 1)
    for i in range(n):
        prefix[i + 1] = prefix[i] + a[i]

    def left_turn_or_flat(i: int, j: int, m: int) -> bool:
        return (prefix[j] - prefix[i]) * (m - j) >= (prefix[m] - prefix[j]) * (j - i)

    def slope_le(i: int, j: int, r: int) -> bool:
        return (prefix[r] - prefix[i]) * (r - j) <= (prefix[r] - prefix[j]) * (r - i)

    dq: deque[int] = deque()
    best_num = 0
    best_den = 1
    have = False

    for r in range(k, n + 1):
        left = r - k
        while len(dq) >= 2 and left_turn_or_flat(dq[-2], dq[-1], left):
            dq.pop()
        dq.append(left)
        while len(dq) >= 2 and slope_le(dq[0], dq[1], r):
            dq.popleft()
        num = prefix[r] - prefix[dq[0]]
        den = r - dq[0]
        if (not have) or num * best_den > best_num * den:
            best_num = num
            best_den = den
            have = True

    g = math.gcd(best_num, best_den)
    return [best_num // g, best_den // g]
